n// \u6d4b\u8bd5\u51fd\u6570\nconst tree = arrayToTree(flatArray)\nconsole.log(JSON.stringify(tree, null, 2)) // \u8f93\u51fa\u7ed3\u679c stringify\u7684\u4e09\u4e2a\u53c2\u6570\uff0c\u7b2c\u4e00\u4e2a\u662fjson\u5bf9\u8c61\uff0c\u7b2c\u4e8c\u4e2a\u662f replacer\uff0c\u7b2c\u4e09\u4e2a\u662f\u7f29\u8fdb\u7a7a\u683c\u6570\n"})}),"\n",(0,r.jsx)(e.h2,{id:"\u89e3\u6790-url",children:"\u89e3\u6790 url"}),"\n",(0,r.jsx)(e.pre,{children:(0,r.jsx)(e.code,{className:"language-js",metastring:'showLineNumbers title="\u5229\u7528URLSearchParams\u89e3\u6790url"',children:"// \u5b9a\u4e49\u89e3\u6790\u51fd\u6570\nfunction parseUrlParams(url) {\n  // \u521b\u5efa URL \u5bf9\u8c61\n  const urlObj = new URL(url)\n\n  // \u521b\u5efa URLSearchParams \u5bf9\u8c61\n  const params = new URLSearchParams(urlObj.search)\n\n  // \u521d\u59cb\u5316\u5b58\u50a8\u7ed3\u679c\u7684\u5bf9\u8c61\n  const result = {}\n\n  // \u904d\u5386 URLSearchParams \u5bf9\u8c61\n  for (const [key, value] of params.entries()) {\n    result[key] = value\n  }\n\n  return result\n}\n\n// \u6d4b\u8bd5\u89e3\u6790\u51fd\u6570\nconst url = 'https://example.com?name=yupi&age=25&location=shanghai'\nconst parsedParams = parseUrlParams(url)\n\nconsole.log(parsedParams)\n// \u8f93\u51fa\u7ed3\u679c\u5982\u4e0b\n// {\n//     name: 'yupi',\n//     age: '25',\n//     location: 'shanghai'\n// }\n"})}),"\n",(0,r.jsx)(e.h2,{id:"\u53cc\u5411\u6570\u636e\u7ed1\u5b9a\u7684\u5b9e\u73b0",children:"\u53cc\u5411\u6570\u636e\u7ed1\u5b9a\u7684\u5b9e\u73b0"}),"\n",(0,r.jsx)(e.pre,{children:(0,r.jsx)(e.code,{className:"language-html",metastring:'showLineNumbers title="defineProperty"',children:"<body>\n  <div id=\"div1\">\n    <input type=\"text\" v-model=\"name\" />\n    <br />\n    \u59d3\u540d\uff1a{{name}}\n  </div>\n\n  <script>\n    // \u83b7\u53d6 input \u5143\u7d20\u548c div \u5bb9\u5668\n    const input = document.querySelector('input[v-model=\"name\"]')\n    const div = document.getElementById('div1')\n\n    function updateView(value) {\n      // \u66f4\u65b0\u89c6\u56fe\n      input.value = value\n      div.innerHTML = div.innerHTML.replace(/\\{\\{name\\}\\}/g, value)\n    }\n\n    // \u521d\u59cb\u5316\u6a21\u578b\u5bf9\u8c61\n    const data = {}\n    Object.defineProperty(data, 'name', {\n      get() {\n        return this._name\n      },\n      set(value) {\n        // \u8bbe\u7f6e\u503c\uff0c\u53c2\u6570\u4e3a\u65b0\u503c\n        this._name = value\n        updateView(value)\n      }\n    })\n\n    // \u8bbe\u7f6e\u521d\u59cb\u503c\n    data.name = ''\n\n    // \u76d1\u542c input \u8f93\u5165\u53d8\u5316\n    input.addEventListener('input', e => {\n      data.name = e.target.value\n    })\n\n    // \u521d\u59cb\u5316\u89c6\u56fe\n    updateView(data.name)\n  <\/script>\n</body>\n"})}),"\n",(0,r.jsx)(e.pre,{children:(0,r.jsx)(e.code,{className:"language-html",metastring:'showLineNumbers title="proxy\u5b9e\u73b0"',children:"<body>\n  <div id=\"div1\">\n    <input type=\"text\" v-model=\"name\" />\n    <br />\n    \u59d3\u540d\uff1a{{name}}\n  </div>\n\n  <script>\n    // \u83b7\u53d6 input \u5143\u7d20\u548c div \u5bb9\u5668\n    const input = document.querySelector('input[v-model=\"name\"]')\n    const div = document.getElementById('div1')\n\n    function updateView(value) {\n      input.value = value\n      div.innerHTML = div.innerHTML.replace(/\\{\\{name\\}\\}/g, value)\n    }\n\n    // \u521d\u59cb\u5316\u6a21\u578b\u5bf9\u8c61\u5e76\u4f7f\u7528 Proxy \u8fdb\u884c\u4ee3\u7406\n    const data = new Proxy(\n      {},\n      {\n        set(target, key, value) {\n          // \u8bbe\u7f6e\u503c\uff0c\u53c2\u6570\u4e3a\u4e09\u4e2a\uff0c\u7b2c\u4e00\u4e2a\u662f\u76ee\u6807\u5bf9\u8c61\uff0c\u7b2c\u4e8c\u4e2a\u662f\u5c5e\u6027\u540d\uff0c\u7b2c\u4e09\u4e2a\u662f\u65b0\u503c\n          target[key] = value\n          if (key === 'name') {\n            updateView(value)\n          }\n          return true\n        },\n        get(target, key) {\n          // \u83b7\u53d6\u503c\uff0c\u53c2\u